  "track.debugging.vz.loop.rel.guess.0": "Release 1.4.1 is out; nobody knows yet when the bug happens.",
  "track.debugging.vz.loop.rel.guess.1": "Release 1.4.2 is out: no crashes in the reports.",
  "track.debugging.vz.loop.rel.guess.2": "Users report a blank screen in the amber rows; there is no stack trace.",
  "track.debugging.vz.loop.rel.guess.3": "Release 1.4.3: the third guess, the cause still unknown.",
  "track.debugging.vz.loop.rel.method.0": "Nothing fixed yet: just run all 8 scenarios on a debug build.",
